"""Red-team differential corpus for packages/lua: name -> Lua 5.4 source.
Each case prints its observations; the comparator diffs Pion (4 modes) against PUC-Rio Lua 5.4.7.
Cases avoid printing addresses (tables/functions) so output is deterministic."""

C = {}
def case(name, src):
    assert name not in C, name
    C[name] = src

# ---------- lexer / syntax ----------
